<script>
  const landing=document.getElementById('landing'), player=document.getElementById('player');
  const start=document.getElementById('startBtn'), close=document.getElementById('closeBtn');
  const pbtn=document.getElementById('playerPlay'), top=document.getElementById('topPlay');
  let playing=true;
  start.onclick=()=>{landing.style.display='none';player.style.display='block'};
  close.onclick=()=>{player.style.display='none';landing.style.display='flex'};
  function toggle(){playing=!playing;pbtn.textContent=playing?'Ⅱ':'▶';top.textContent=playing?'Ⅱ':'▶'}
  pbtn.onclick=toggle;top.onclick=toggle;
</script>
